import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import PlaceHereModal from './PlaceHereModal';
export default class PlacementTargetButton extends Component {
  view() {
    const {
      report,
      controller
    } = this.attrs;
    const spot = controller.spot(report.spot);
    const label = spot ? spot.label() : report.spot;
    return m("button", {
      type: "button",
      className: "PlacementTarget",
      title: app.translator.trans('fof-scavenger-hunt.forum.placement_mode.target', {
        spot: label
      }, true),
      disabled: !controller.part(),
      onclick: e => {
        e.preventDefault();
        e.stopPropagation();
        app.modal.show(PlaceHereModal, {
          report,
          controller
        });
      }
    }, m(Icon, {
      name: "fas fa-map-pin"
    }), m("span", {
      className: "PlacementTarget-label"
    }, label, report.contextId ? ` #${report.contextId}` : ''));
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/placement/PlacementTargetButton', PlacementTargetButton);